'\''1i /* xref: a symbol and its transitive callees, extracted into /xref/ */
static int xbudget = 200;		/* max extents in one closure */
static char *xref_seedft;		/* the file type the seed was found in */
/* column 0 anchoring rejects call sites; override with :xd for other languages */
static char xref_defpat[] = "^[A-Za-z_].*\\<%s\\>[ \t]*\\([^;]*$|"
	"^[ \t]*def[ \t]+%s\\>|^[ \t]*func[ \t]+.*\\<%s\\>|"
	"^[ \t]*(?:function[ \t]+%s\\>|%s[ \t]*\\(\\))";
/* a call is a name before a '\''('\'', except in shell, where it is a command */
static char xref_callpat[] = "(\\<[A-Za-z_][A-Za-z0-9_]*)[ \t]*\\(";
static char xref_shcallpat[] = "(?:^[ \t]*|[;&|(`{][ \t]*|"
	"\\<(?:then|else|do)[ \t]+)([A-Za-z_][A-Za-z0-9_]*)";

static int xref_blank(char *s)
{
	for (; *s; s++)
		if (!isspace((unsigned char)*s))
			return 0;
	return 1;
}

static int xref_indent(char *s)
{
	int i = 0;
	for (; s[i] == '\'' '\'' || s[i] == '\''\t'\''; i++);
	return i;
}

/* a definition ends at its last non-blank line, never at the gap after it */
static void xref_trim(struct lbuf *lb, int line, int *row)
{
	while (*row - 1 > line && xref_blank(lbuf_get(lb, *row - 1)))
		--*row;
}

/* the last line of the definition at line, mode chosen from the line itself */
static int xref_bound(struct lbuf *lb, int line, int *end)
{
	char *s = lbuf_get(lb, line), *t;
	int row = line, off = 0, i, n = lbuf_len(lb), brow = line;
	if (!s)
		return 1;
	if (!strchr(s, '\''{'\'')) {		/* a brace on one of the next lines */
		for (i = line + 1; i < n && i < line + 3; i++) {
			t = lbuf_get(lb, i);
			if (xref_blank(t))
				continue;
			if (t[xref_indent(t)] == '\''{'\'')
				brow = i;
			break;
		}
	}
	if (strchr(lbuf_get(lb, brow), '\''{'\'')) {	/* c, java, js, go, rust, ... */
		row = brow;
		if (!lbuf_pair(lb, "{}", 2, &row, &off)) {
			*end = row;
			return 0;
		}		/* braces in strings and char literals lose the
				 * matcher: the first column 0 close is the end */
		for (row = brow + 1; row < n && row < brow + 500; row++)
			if (*lbuf_get(lb, row) == '\''}'\'') {
				*end = row;
				return 0;
			}
	}
	for (i = strlen(s); i > 0 && isspace((unsigned char)s[i-1]); i--);
	if (i > 0 && s[i-1] == '\'':'\'') {	/* python, yaml, nim, ... */
		i = xref_indent(s);
		for (row = line + 1; row < n; row++) {
			t = lbuf_get(lb, row);
			if (!xref_blank(t) && xref_indent(t) <= i)
				break;
		}
		xref_trim(lb, line, &row);
		*end = row - 1;
		return 0;
	}				/* shell, lisp, make, asm, anything weird */
	for (row = line + 1; row < n && row < line + 60; row++)
		if (!isspace((unsigned char)*lbuf_get(lb, row)))
			break;
	xref_trim(lb, line, &row);
	*end = row - 1;
	return 0;
}

/* the :xd pattern with %s expanded to sym */
static char *xref_pat(char *sym)
{
	char *s = xdefreg_pat ? xdefreg_pat->s : xref_defpat;
	sbuf_smake(sb, 256)
	for (; *s; s++) {
		if (s[0] == '\''%'\'' && s[1] == '\''s'\'') {
			sbuf_str(sb, sym)
			s++;
		} else
			sbuf_chr(sb, *s)
	}
	sbufn_ret(sb, sb->s)
}

/* the definition of sym, as a line in the buffer this leaves current */
static int xref_resolve(char *sym, int *outline)
{
	char *pat = xref_pat(sym);
	int row = 0, off = 0, ret, last = 0;
	ex_krsset(pat, 1);
	free(pat);
	fspos = 0;
	/* a closure is one language: a hit in another one is a coincidence.
	 * fs_search wraps the listing, so a hit behind the last one is the end */
	while ((ret = fs_search(1, &row, &off))) {
		if (syn_filetype(xb_path) == xref_seedft)
			break;
		if (fspos <= last) {
			ret = 0;
			break;
		}
		last = fspos;
	}
	if (ret)
		*outline = row;
	return ret;
}

/* reserved in both C like languages and shell, so never a definition */
static char *xref_kwds[] = {"if", "else", "elif", "fi", "for", "while", "do",
	"done", "case", "esac", "switch", "return", "sizeof", "then", "in",
	"until", "select", "break", "continue", "function", "defined"};

static int xref_kwd(char *sym, int len)
{
	int i;
	for (i = 0; i < (int)LEN(xref_kwds); i++)
		if ((int)strlen(xref_kwds[i]) == len &&
				!memcmp(xref_kwds[i], sym, len))
			return 1;
	return 0;
}

static int xref_seen(sbuf *seen, char *sym, int len)
{
	char *s = seen->s, *e, *lim = seen->s + seen->s_n;
	while (s < lim && (e = memchr(s, '\''\n'\'', lim - s))) {
		if (e - s == len && !memcmp(s, sym, len))
			return 1;
		s = e + 1;
	}
	return 0;
}

/* queue every identifier called within an extent, once each */
static void xref_scan(struct lbuf *lb, int b, int e, sbuf *queue, sbuf *seen)
{
	static rset *rs[2];
	char *s;
	int grps[8], off, len, i, sh = syn_filetype(xb_path) == sh_ft;
	if (!rs[sh] && !(rs[sh] = rset_smake(sh ? xref_shcallpat : xref_callpat, 0)))
		return;
	for (i = b; i <= e; i++) {
		if (!(s = lbuf_get(lb, i)))
			break;
		for (off = 0; rset_find(rs[sh], s + off, grps, off ? REG_NOTBOL : 0) >= 0;) {
			len = grps[3] - grps[2];
			if (!xref_kwd(s + off + grps[2], len) &&
					!xref_seen(seen, s + off + grps[2], len)) {
				sbuf_mem(queue, s + off + grps[2], len)
				sbuf_chr(queue, '\''\n'\'')
				sbuf_mem(seen, s + off + grps[2], len)
				sbuf_chr(seen, '\''\n'\'')
			}
			off += MAX(grps[1], 1);
		}
	}
}

/* extract sym and its callees down to maxdepth (0 is unlimited) into /xref/ */
static char *xref_build(char *sym, int maxdepth)
{
	sbuf *cur, *nxt, *seen, *done, *out, *tmp;
	struct lbuf *lb;
	struct buf *obuf = ex_buf;
	char key[1024], nbuf[32], *s, *e;
	int start, end, depth, i, n = 0;
	if (!lbuf_len(tempbufs[1].lb))
		return "xref: no listing, run :fd";
	sbuf_make(cur, 256)
	sbuf_make(nxt, 256)
	sbuf_make(seen, 256)
	sbuf_make(done, 256)
	sbuf_make(out, 4096)
	xref_seedft = syn_filetype(xb_path);
	sbuf_str(cur, sym)
	sbuf_chr(cur, '\''\n'\'')
	sbuf_str(seen, sym)
	sbuf_chr(seen, '\''\n'\'')
	for (depth = 0; cur->s_n && n < xbudget; depth++) {
		if (maxdepth && depth >= maxdepth)
			break;		/* 1gx is the seed alone */
		for (s = cur->s; s < cur->s + cur->s_n; s = e + 1) {
			if (n >= xbudget)
				break;
			if (!(e = memchr(s, '\''\n'\'', cur->s + cur->s_n - s)))
				break;
			*e = '\''\0'\'';
			if (!xref_resolve(s, &start))
				continue;	/* the resolver is the filter */
			i = snprintf(key, sizeof(key), "%s:%d", xb_path, start);
			if (xref_seen(done, key, i) || xref_bound(xb, start, &end))
				continue;
			sbuf_mem(done, key, i)
			sbuf_chr(done, '\''\n'\'')
			n++;
			sbuf_str(out, xb_path)		/* the header owns its line, */
			sbuf_chr(out, '\'':'\'')		/* so the body reads verbatim */
			itoa(start + 1, nbuf);
			sbuf_str(out, nbuf)
			sbuf_chr(out, '\''\n'\'')
			for (i = start; i <= end; i++)
				sbuf_str(out, lbuf_get(xb, i))
			xref_scan(xb, start, end, nxt, seen);
		}
		tmp = cur;
		cur = nxt;
		nxt = tmp;
		sbuf_cut(nxt, 0)
	}
	sbufn_null(out)
	/* resolution opens buffers behind ex_edit'\''s back, which leaves no mtime */
	for (i = xbufcur - 1; i >= 0 && bufs[i].mtime == -1; i--)
		ex_bufpostfix(&bufs[i], 1);
	if (ex_buf != obuf) {		/* resolution browses, gx does not jump */
		exbuf_save(ex_buf)
		ex_buf = obuf;
		exbuf_load(ex_buf)
		syn_setft(xb_ft);
	}
	lb = tempbufs[XREF_BUF].lb;
	s = NULL;
	if (n) {			/* every extent is in the seed'\''s language */
		tempbufs[XREF_BUF].ft = xref_seedft;
		if (lbuf_len(lb))
			lbuf_edit(lb, NULL, 0, lbuf_len(lb), 0, 0);
		temp_pos(XREF_BUF, 0, 0, 0);
		temp_write(XREF_BUF, out->s);
		temp_pos(XREF_BUF, 0, 0, 0);
	} else				/* nothing found, so nothing is replaced */
		s = "xref: no definition";
	sbuf_free(cur)
	sbuf_free(nxt)
	sbuf_free(seen)
	sbuf_free(done)
	sbuf_free(out)
	return s;
}

